CREATE   VIEW [FO].[vwLedgerTrans]
AS
SELECT 
	LT.[ACCOUNTDISPLAYVALUE],
	LT.[JOURNALNUMBER],
	LT.[SUBLEDGERVOUCHER] AS [VOUCHER],
	LT.[ACCOUNTINGDATE],
	--LT.[POSTINGLAYER],
	--LT.[LEDGERACCOUNT],
	LT.[TRANSACTIONCURRENCYCODE],
	LT.[TRANSACTIONCURRENCYAMOUNT],
	LT.[ACCOUNTINGCURRENCYAMOUNT],
	LT.[REPORTINGCURRENCYAMOUNT],
	--LT.[DESCRIPTION],
	--LT.[QUANTITY],
	LT.[POSTINGTYPE],
	LT.[JOURNALCATEGORY],
	LT.[ISCORRECTION],
	LT.[ISCREDIT],
	LT.[ACKNOWLEDGEMENTDATE],
	LT.[DOCUMENTDATE],
	LT.[DOCUMENTNUMBER],
	LT.RICSINTERCOMPANY AS INTERCOMPANY,
	LT.RICSINTERIMREPORTINGENTITY AS INTERIMREPORTINGENTITY,
	--LT.[LEDGERNAME],
	LT.[RECID] AS [GENERALJOURNALACCOUNTENTRYRECID],
	LT.[MAINACCOUNT],
	LT.[TEXT],
	--LT.[ALLOCATIONLEVEL],
	LT.[PAYMENTREFERENCE],
	LT.[REASONREF],
	LT.[DATAAREAID],
	LT.[RECID],
	LT.[RICSPRODUCTCODE] AS [productcode],
	LT.[RICSPRODUCTGROUP] AS [productgroup],
	LT.[RICSCOSTCENTER] AS [CostCenter],
	LT.[RICSCOUNTRY] AS [Country],
	LT.TB_Category_Code,
	LT.[Createdby1],
	LT.[createddatetime1],
	LT.ACCOUNTNUM,
	CASE
		WHEN LT.DATAAREAID = 'rgre' THEN LT.RICSINTERIMREPORTINGENTITY ELSE LT.RICSINTERCOMPANY
		END AS 'IRE Adjusted'
FROM [synapse_fo].[LEDGERTRANS_RICS] LT
WHERE LT.[DATAAREAID] NOT IN ('RICS', 'RGRE')
